def search_gifs(workspace_id, q, credential_id=None, limit=None, offset=None, lang=None, rating=None, bundle=None, use_cache=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, hashlib, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        # preserve vendor-like prefixes in schema examples
        h = hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:16]
        return f"{prefix}{h}"

    def _normalize_bool(v, default=False):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _window_start(now, window_seconds):
        if window_seconds == 60:
            return now.replace(second=0, microsecond=0)
        if window_seconds == 300:
            m = (now.minute // 5) * 5
            return now.replace(minute=m, second=0, microsecond=0)
        if window_seconds == 3600:
            return now.replace(minute=0, second=0, microsecond=0)
        if window_seconds == 86400:
            return now.replace(hour=0, minute=0, second=0, microsecond=0)
        return now.replace(second=0, microsecond=0)

    def _get_or_create_usage_row(usage_rows, workspace_id_, tool_name_, window_seconds_, ws_iso):
        for r in usage_rows:
            if (isinstance(r, dict)
                and r.get("workspace_id") == workspace_id_
                and r.get("tool_name") == tool_name_
                and r.get("window_seconds") == window_seconds_
                and r.get("window_start") == ws_iso):
                return r
        row = {
            "id": _new_id("gph_use_"),
            "workspace_id": workspace_id_,
            "tool_name": tool_name_,
            "window_start": ws_iso,
            "window_seconds": window_seconds_,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        usage_rows.append(row)
        return row

    def _reserve_quota(usage_rows, workspace_id_, tool_name_):
        # Configured limits are not present in schema; enforce a safe default per-minute cap.
        # Business rule says: if increment would exceed configured limits, fail with quota_exceeded.
        limit_per_minute = 60
        now = datetime.datetime.utcnow()
        window_seconds = 60
        ws = _window_start(now, window_seconds).isoformat() + "Z"
        row = _get_or_create_usage_row(usage_rows, workspace_id_, tool_name_, window_seconds, ws)
        cur = int(row.get("request_count") or 0)
        if cur + 1 > limit_per_minute:
            return False, row
        row["request_count"] = cur + 1
        # keep invariant request_count = success_count + error_count by not changing success/error yet
        row["updated_at"] = _now()
        return True, row

    def _finalize_usage(row, succeeded):
        if not isinstance(row, dict):
            return
        sc = int(row.get("success_count") or 0)
        ec = int(row.get("error_count") or 0)
        if succeeded:
            sc += 1
        else:
            ec += 1
        row["success_count"] = sc
        row["error_count"] = ec
        row["request_count"] = sc + ec
        row["updated_at"] = _now()

    def _cache_key(ws_id, tool, params):
        norm = json.dumps(params, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256((ws_id + "|" + tool + "|" + norm).encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", workspace_id=workspace_id)
    if not isinstance(q, str) or len(q) < 1:
        return _err("VALIDATION_ERROR", "q must be a non-empty string.", q=q)
    if credential_id is not None:
        if not isinstance(credential_id, str) or not re.match(r"^gph_cred_[A-Za-z0-9]+$", credential_id):
            return _err("VALIDATION_ERROR", "Invalid credential_id format.", credential_id=credential_id)
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", limit=limit)
    if offset is not None:
        if not isinstance(offset, int) or offset < 0:
            return _err("VALIDATION_ERROR", "offset must be an integer >= 0.", offset=offset)
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 1:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 1.", cache_ttl_seconds=cache_ttl_seconds)
    ub = _normalize_bool(use_cache, default=False)
    if ub is None:
        return _err("VALIDATION_ERROR", "use_cache must be boolean when provided.", use_cache=use_cache)

    limit_v = limit if limit is not None else 25
    offset_v = offset if offset is not None else 0

    # Load store
    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    reqs = _load("gif_requests.json")
    resps = _load("gif_responses.json")
    usage = _load("usage_counters.json")

    # Resolve workspace (must exist and not be deleted)
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Workspaces in status 'deleted' must reject new gif_requests inserts.", workspace_id=workspace_id)

    # Resolve language default
    lang_v = lang if isinstance(lang, str) and lang else (ws.get("default_language") if isinstance(ws.get("default_language"), str) else None)

    # Resolve credential: if provided, authenticate by id; else pick any active giphy credential in workspace.
    cred = None
    if credential_id is not None:
        cred = next((c for c in creds if isinstance(c, dict) and c.get("id") == credential_id), None)
        if not cred:
            return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)
        if cred.get("workspace_id") != workspace_id:
            return _err("UNAUTHORIZED", "Credential must belong to the workspace (business rule).", workspace_id=workspace_id, credential_id=credential_id)
        if cred.get("status") != "active":
            return _err("UNAUTHORIZED", "Credential must be active to be used (business rule).", credential_id=credential_id, status=cred.get("status"))
        if cred.get("provider") != "giphy":
            return _err("VALIDATION_ERROR", "credential_id provider must be 'giphy'.", credential_id=credential_id)
    else:
        cred = next((c for c in creds
                     if isinstance(c, dict)
                     and c.get("workspace_id") == workspace_id
                     and c.get("provider") == "giphy"
                     and c.get("status") == "active"), None)
        if cred is None:
            # Ambient auth: search for a working combination; none exists.
            return _err("UNAUTHORIZED", "No active Giphy credential available for this workspace.", workspace_id=workspace_id)

    # Compute cache key if caching enabled
    cache_key = None
    if ub:
        ck_params = {
            "q": q,
            "limit": limit_v,
            "offset": offset_v,
            "lang": lang_v,
            "rating": rating,
            "bundle": bundle,
        }
        cache_key = _cache_key(workspace_id, "search_gifs", ck_params)

    # Create gif_request row (exactly one per call)
    req_id = _new_id("gph_req_")
    now_iso = _now()
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "credential_id": cred.get("id"),
        "tool_name": "search_gifs",
        "input": {},  # current tool surface stores empty object
        "cache_key": cache_key,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    reqs.append(req_row)

    # Check cache before reserving quota/upstream
    served_from_cache = False
    cached_payload = None
    if ub and cache_key:
        now_dt = datetime.datetime.utcnow()
        # find a prior request with same workspace/cache_key with a non-expired response
        for r in reversed(reqs[:-1]):  # prior only
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id or r.get("cache_key") != cache_key:
                continue
            # response must exist
            resp = next((x for x in resps if isinstance(x, dict) and x.get("request_id") == r.get("id") and x.get("workspace_id") == workspace_id), None)
            if not resp:
                continue
            exp = _parse_dt(resp.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            cached_payload = resp
            break

    # Transition queued -> running
    req_row["status"] = "running"
    req_row["updated_at"] = _now()

    # Serve from cache if available
    if cached_payload is not None:
        served_from_cache = True
        # Complete request as succeeded without consuming quota/upstream
        req_row["status"] = "succeeded"
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now()
        req_row["completed_at"] = _now()
        # Create a response row for this request (unique request_id), marked from_cache=true
        ttl = cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else 60
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z"
        resp_row = {
            "id": _new_id("gph_resp_"),
            "request_id": req_id,
            "workspace_id": workspace_id,
            "from_cache": True,
            "expires_at": expires_at,
            "raw_json": cached_payload.get("raw_json") if isinstance(cached_payload.get("raw_json"), dict) else {},
            "gif_items": cached_payload.get("gif_items") if isinstance(cached_payload.get("gif_items"), list) else [],
            "result_count": int(cached_payload.get("result_count") or 0),
            "created_at": _now(),
            "updated_at": _now(),
        }
        # Ensure constraint result_count=array_length
        resp_row["result_count"] = len(resp_row["gif_items"])
        resps.append(resp_row)
        # last_used_at on credential for successful use
        cred["last_used_at"] = _now()
        cred["updated_at"] = _now()
        _save("gif_requests.json", reqs)
        _save("gif_responses.json", resps)
        _save("api_credentials.json", creds)
        _save("usage_counters.json", usage)
        return {
            "data": {
                "request": req_row,
                "response": resp_row,
                "meta": {"limit": limit_v, "offset": offset_v, "from_cache": True}
            }
        }

    # Reserve quota before "upstream"
    ok, usage_row = _reserve_quota(usage, workspace_id, "search_gifs")
    if not ok:
        # Fail request with quota_exceeded; do not call upstream
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Workspace quota exceeded for search_gifs in current window"
        req_row["http_status"] = None
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now()
        req_row["completed_at"] = _now()
        _finalize_usage(usage_row, succeeded=False)
        _save("gif_requests.json", reqs)
        _save("usage_counters.json", usage)
        return _err("QUOTA_EXCEEDED", "Workspace quota exceeded for search_gifs in current window.", workspace_id=workspace_id, tool_name="search_gifs")

    # Simulated upstream call (offline). Record http_status since it "reached upstream".
    # Produce deterministic-ish fake results from query and pagination.
    random_seed = int(hashlib.sha256((workspace_id + "|" + q).encode("utf-8")).hexdigest()[:8], 16)
    rnd = random.Random(random_seed)
    total_available = 200
    start = min(offset_v, total_available)
    end = min(start + limit_v, total_available)
    items = []
    for i in range(start, end):
        gid = hashlib.sha1(f"{q}|{i}|{workspace_id}".encode("utf-8")).hexdigest()[:10]
        items.append({
            "giphy_id": gid,
            "title": f"{q} #{i}",
            "rating": rating,
            "username": "",
            "url": f"https://giphy.com/gifs/{gid}",
            "images": {
                "original": {"url": f"https://media.giphy.com/media/{gid}/giphy.gif"},
                "preview": {"url": f"https://media.giphy.com/media/{gid}/giphy-preview.gif"},
            }
        })
        # minor randomness in username/title
        if rnd.random() < 0.1:
            items[-1]["username"] = "giphy"
    raw_json = {
        "data": items,
        "pagination": {"total_count": total_available, "count": len(items), "offset": offset_v},
        "meta": {"status": 200, "msg": "OK", "response_id": hashlib.md5(req_id.encode("utf-8")).hexdigest()},
        "request": {"q": q, "limit": limit_v, "offset": offset_v, "lang": lang_v, "rating": rating, "bundle": bundle},
    }

    # Succeed
    req_row["http_status"] = 200
    req_row["status"] = "succeeded"
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["updated_at"] = _now()
    req_row["completed_at"] = _now()

    ttl = cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else 60
    expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z" if cache_key else None
    resp_row = {
        "id": _new_id("gph_resp_"),
        "request_id": req_id,
        "workspace_id": workspace_id,
        "from_cache": False,
        "expires_at": expires_at,
        "raw_json": raw_json,
        "gif_items": items,
        "result_count": len(items),
        "created_at": _now(),
        "updated_at": _now(),
    }
    resps.append(resp_row)

    _finalize_usage(usage_row, succeeded=True)
    cred["last_used_at"] = _now()
    cred["updated_at"] = _now()

    _save("gif_requests.json", reqs)
    _save("gif_responses.json", resps)
    _save("api_credentials.json", creds)
    _save("usage_counters.json", usage)

    return {
        "data": {
            "request": req_row,
            "response": resp_row,
            "meta": {"limit": limit_v, "offset": offset_v, "from_cache": False}
        }
    }

def get_random_gif(workspace_id, credential_id=None, tag=None, rating=None, lang=None, use_cache=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, hashlib, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        h = hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:16]
        return f"{prefix}{h}"

    def _normalize_bool(v, default=False):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _window_start(now, window_seconds):
        return now.replace(second=0, microsecond=0)

    def _get_or_create_usage_row(usage_rows, workspace_id_, tool_name_, window_seconds_, ws_iso):
        for r in usage_rows:
            if (isinstance(r, dict)
                and r.get("workspace_id") == workspace_id_
                and r.get("tool_name") == tool_name_
                and r.get("window_seconds") == window_seconds_
                and r.get("window_start") == ws_iso):
                return r
        row = {
            "id": _new_id("gph_use_"),
            "workspace_id": workspace_id_,
            "tool_name": tool_name_,
            "window_start": ws_iso,
            "window_seconds": window_seconds_,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        usage_rows.append(row)
        return row

    def _reserve_quota(usage_rows, workspace_id_, tool_name_):
        limit_per_minute = 60
        now = datetime.datetime.utcnow()
        window_seconds = 60
        ws = _window_start(now, window_seconds).isoformat() + "Z"
        row = _get_or_create_usage_row(usage_rows, workspace_id_, tool_name_, window_seconds, ws)
        cur = int(row.get("request_count") or 0)
        if cur + 1 > limit_per_minute:
            return False, row
        row["request_count"] = cur + 1
        row["updated_at"] = _now()
        return True, row

    def _finalize_usage(row, succeeded):
        if not isinstance(row, dict):
            return
        sc = int(row.get("success_count") or 0)
        ec = int(row.get("error_count") or 0)
        if succeeded:
            sc += 1
        else:
            ec += 1
        row["success_count"] = sc
        row["error_count"] = ec
        row["request_count"] = sc + ec
        row["updated_at"] = _now()

    def _cache_key(ws_id, tool, params):
        norm = json.dumps(params, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256((ws_id + "|" + tool + "|" + norm).encode("utf-8")).hexdigest()

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", workspace_id=workspace_id)
    if credential_id is not None:
        if not isinstance(credential_id, str) or not re.match(r"^gph_cred_[A-Za-z0-9]+$", credential_id):
            return _err("VALIDATION_ERROR", "Invalid credential_id format.", credential_id=credential_id)
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 1:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 1.", cache_ttl_seconds=cache_ttl_seconds)
    ub = _normalize_bool(use_cache, default=False)
    if ub is None:
        return _err("VALIDATION_ERROR", "use_cache must be boolean when provided.", use_cache=use_cache)

    # Load
    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    reqs = _load("gif_requests.json")
    resps = _load("gif_responses.json")
    usage = _load("usage_counters.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Workspaces in status 'deleted' must reject new gif_requests inserts.", workspace_id=workspace_id)

    lang_v = lang if isinstance(lang, str) and lang else (ws.get("default_language") if isinstance(ws.get("default_language"), str) else None)

    cred = None
    if credential_id is not None:
        cred = next((c for c in creds if isinstance(c, dict) and c.get("id") == credential_id), None)
        if not cred:
            return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)
        if cred.get("workspace_id") != workspace_id:
            return _err("UNAUTHORIZED", "Credential must belong to the workspace (business rule).", workspace_id=workspace_id, credential_id=credential_id)
        if cred.get("status") != "active":
            return _err("UNAUTHORIZED", "Credential must be active to be used (business rule).", credential_id=credential_id, status=cred.get("status"))
        if cred.get("provider") != "giphy":
            return _err("VALIDATION_ERROR", "credential_id provider must be 'giphy'.", credential_id=credential_id)
    else:
        cred = next((c for c in creds
                     if isinstance(c, dict)
                     and c.get("workspace_id") == workspace_id
                     and c.get("provider") == "giphy"
                     and c.get("status") == "active"), None)
        if cred is None:
            return _err("UNAUTHORIZED", "No active Giphy credential available for this workspace.", workspace_id=workspace_id)

    cache_key = None
    if ub:
        ck_params = {"tag": tag, "lang": lang_v, "rating": rating}
        cache_key = _cache_key(workspace_id, "get_random_gif", ck_params)

    # Create request row
    req_id = _new_id("gph_req_")
    now_iso = _now()
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "credential_id": cred.get("id"),
        "tool_name": "get_random_gif",
        "input": {},
        "cache_key": cache_key,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    reqs.append(req_row)

    # Cache check
    cached_payload = None
    if ub and cache_key:
        now_dt = datetime.datetime.utcnow()
        for r in reversed(reqs[:-1]):
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id or r.get("cache_key") != cache_key:
                continue
            resp = next((x for x in resps if isinstance(x, dict) and x.get("request_id") == r.get("id") and x.get("workspace_id") == workspace_id), None)
            if not resp:
                continue
            exp = _parse_dt(resp.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            cached_payload = resp
            break

    req_row["status"] = "running"
    req_row["updated_at"] = _now()

    if cached_payload is not None:
        req_row["status"] = "succeeded"
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now()
        req_row["completed_at"] = _now()
        ttl = cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else 60
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z"
        resp_row = {
            "id": _new_id("gph_resp_"),
            "request_id": req_id,
            "workspace_id": workspace_id,
            "from_cache": True,
            "expires_at": expires_at,
