    cred = None
    if credential_id is not None:
        cred = next((c for c in creds if isinstance(c, dict) and c.get("id") == credential_id), None)
        if not cred:
            return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)
        if cred.get("workspace_id") != workspace_id:
            return _err("UNAUTHORIZED", "Credential must belong to the workspace (business rule).", workspace_id=workspace_id, credential_id=credential_id)
        if cred.get("status") != "active":
            return _err("UNAUTHORIZED", "Credential must be active to be used (business rule).", credential_id=credential_id, status=cred.get("status"))
        if cred.get("provider") != "giphy":
            return _err("VALIDATION_ERROR", "credential_id provider must be 'giphy'.", credential_id=credential_id)
    else:
        cred = next((c for c in creds
                     if isinstance(c, dict)
                     and c.get("workspace_id") == workspace_id
                     and c.get("provider") == "giphy"
                     and c.get("status") == "active"), None)
        if cred is None:
            return _err("UNAUTHORIZED", "No active Giphy credential available for this workspace.", workspace_id=workspace_id)

    cache_key = None
    if ub:
        ck_params = {"limit": limit_v, "offset": offset_v, "rating": rating, "bundle": bundle}
        cache_key = _cache_key(workspace_id, "get_trending_gifs", ck_params)

    # Create request
    req_id = _new_id("gph_req_")
    now_iso = _now()
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "credential_id": cred.get("id"),
        "tool_name": "get_trending_gifs",
        "input": {},
        "cache_key": cache_key,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    reqs.append(req_row)

    # Cache check
    cached_payload = None
    if ub and cache_key:
        now_dt = datetime.datetime.utcnow()
        for r in reversed(reqs[:-1]):
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id or r.get("cache_key") != cache_key:
                continue
            resp = next((x for x in resps if isinstance(x, dict) and x.get("request_id") == r.get("id") and x.get("workspace_id") == workspace_id), None)
            if not resp:
                continue
            exp = _parse_dt(resp.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            cached_payload = resp
            break

    req_row["status"] = "running"
    req_row["updated_at"] = _now()

