def create_workspace(name, default_language=None, default_region=None, **_extra):
    import json, os, datetime, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(existing):
        # Observed ids look like gph_ws_<base62-ish>. Keep it simple and collision-checked.
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        for _ in range(200):
            suffix = "".join(secrets.choice(alphabet) for _ in range(26))
            _id = "gph_ws_" + suffix
            if _id not in existing:
                return _id
        # very unlikely fallback
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        _id = "gph_ws_" + ts
        if _id in existing:
            _id = _id + "X"
        return _id

    # Validate inputs
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string.", name=name)
    norm_name = name.strip()
    if len(norm_name) < 1 or len(norm_name) > 200:
        return _err("VALIDATION_ERROR", "name must be 1-200 characters.", name=name)

    if default_language is not None:
        if not isinstance(default_language, str):
            return _err("VALIDATION_ERROR", "default_language must be a string.", default_language=default_language)
        if not (2 <= len(default_language) <= 10):
            return _err("VALIDATION_ERROR", "default_language length must be 2-10.", default_language=default_language)

    if default_region is not None:
        if not isinstance(default_region, str):
            return _err("VALIDATION_ERROR", "default_region must be a string.", default_region=default_region)
        if not (2 <= len(default_region) <= 10):
            return _err("VALIDATION_ERROR", "default_region length must be 2-10.", default_region=default_region)

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        return _err("CONFLICT", "Datastore corrupted: workspaces.json must contain a JSON array.")

    # Enforce unique(name) constraint (case-sensitive, as per schema; normalize only whitespace)
    for w in workspaces:
        if isinstance(w, dict) and w.get("name") == norm_name:
            return _err(
                "CONFLICT",
                "Workspace name already exists (unique(name) constraint).",
                name=norm_name
            )

    existing_ids = set()
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            existing_ids.add(w["id"])

    now = _now()
    ws_id = _new_id(existing_ids)

    row = {
        "id": ws_id,
        "name": norm_name,
        "status": "active",
        "default_language": default_language,
        "default_region": default_region,
        "created_at": now,
        "updated_at": now,
    }

    workspaces.append(row)
    _save("workspaces.json", workspaces)

    return {"workspace": row}

def update_workspace(workspace_id, name=None, default_language=None, default_region=None, status=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "Invalid name.")
    if default_language is not None:
        if not isinstance(default_language, str) or not (2 <= len(default_language) <= 10):
            return _err("VALIDATION_ERROR", "Invalid default_language.")
    if default_region is not None:
        if not isinstance(default_region, str) or not (2 <= len(default_region) <= 10):
            return _err("VALIDATION_ERROR", "Invalid default_region.")
    if status is not None:
        if status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status.")

    # Load
    workspaces = _load("workspaces.json")

    ws = None
    for r in workspaces:
        if isinstance(r, dict) and r.get("id") == workspace_id:
            ws = r
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Refuse any updates once deleted
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Workspace is deleted and cannot be updated.", from_status="deleted")

    # Determine whether there is any change
    changes = {}
    if name is not None and name != ws.get("name"):
        # unique(name)
        for r in workspaces:
            if isinstance(r, dict) and r.get("id") != workspace_id and r.get("name") == name:
                return _err("CONFLICT", "Workspace name must be unique.", field="name")
        changes["name"] = name

    if default_language is not None and default_language != ws.get("default_language"):
        changes["default_language"] = default_language

    if default_region is not None and default_region != ws.get("default_region"):
        changes["default_region"] = default_region

    if status is not None and status != ws.get("status"):
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": []
        }
        cur = ws.get("status")
        if cur not in transitions or status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Illegal workspace status transition.", from_status=cur, to_status=status)
        changes["status"] = status

    if not changes:
        # No success without effect
        return _err("CONFLICT", "No changes to apply.")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for k, v in changes.items():
        ws[k] = v
    ws["updated_at"] = now

    _save("workspaces.json", workspaces)

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"workspace": ws, "updated_fields": sorted(list(changes.keys())), "latency_ms": latency_ms}

