    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if provider != "giphy":
        return _err("VALIDATION_ERROR", "Unsupported provider.", provider=provider)
    if not isinstance(api_key, str) or len(api_key) < 1:
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if status is None:
        status = "active"
    if status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")

    ws = None
    for r in workspaces:
        if isinstance(r, dict) and r.get("id") == workspace_id:
            ws = r
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot create credentials for a deleted workspace.", workspace_id=workspace_id)

    # fingerprint (stable)
    fp = hashlib.sha256(api_key.encode("utf-8")).hexdigest()

    # unique(workspace_id, provider, key_fingerprint)
    for r in creds:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == workspace_id and r.get("provider") == provider and r.get("key_fingerprint") == fp:
            return _err("CONFLICT", "Credential with same key already exists for this workspace/provider.", key_fingerprint=fp)

    # "Encrypt" and store (offline simulation): store as base64 with random salt prefix so ciphertext differs per insert
    salt = secrets.token_bytes(16)
    ct = base64.b64encode(salt + api_key.encode("utf-8")).decode("ascii")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_id = "gph_cred_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]

    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "provider": provider,
        "api_key_ciphertext": ct,
        "key_fingerprint": fp,
        "status": status,
        "created_at": now,
        "updated_at": now,
        "last_used_at": None
    }
    creds.append(row)
    _save("api_credentials.json", creds)

    # Return metadata only (no raw key)
    return {
        "credential": {
            "id": row["id"],
            "workspace_id": row["workspace_id"],
            "provider": row["provider"],
            "key_fingerprint": row["key_fingerprint"],
            "status": row["status"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
            "last_used_at": row["last_used_at"]
        }
    }

def update_api_credential(workspace_id, credential_id, status=None, api_key=None, **_extra):
    import json, os, datetime, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _fingerprint(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _ciphertext_placeholder(k):
        # Offline placeholder; must not store plaintext.
        # Keep stable-ish but non-reversible. Prefix hints it's encrypted material.
        return "v1:enc:" + hashlib.sha256(("giphy|" + k).encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^gph_ws_[A-Za-z0-9]+$.", workspace_id=workspace_id)
    if not isinstance(credential_id, str) or not re.match(r"^gph_cred_[A-Za-z0-9]+$", credential_id):
        return _err("VALIDATION_ERROR", "credential_id must match ^gph_cred_[A-Za-z0-9]+$.", credential_id=credential_id)

    if status is not None and status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked.", status=status)
    if api_key is not None and (not isinstance(api_key, str) or len(api_key) < 1):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided.", api_key=api_key)

    if status is None and api_key is None:
        return _err("VALIDATION_ERROR", "No fields to update; provide status and/or api_key.")

    workspaces = _load("workspaces.json")
    creds = _load("api_credentials.json")
    if not isinstance(workspaces, list) or not isinstance(creds, list):
        return _err("CONFLICT", "Datastore corrupted: expected JSON arrays in workspaces.json and api_credentials.json.")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Locate credential
    cred_idx = None
    cred = None
    for i, c in enumerate(creds):
        if isinstance(c, dict) and c.get("id") == credential_id:
            cred_idx = i
            cred = c
            break
    if cred is None:
        return _err("NOT_FOUND", "Credential not found.", credential_id=credential_id)

    # Enforce "credential must belong to the given workspace"
    # IMPORTANT: accept valid updates when it DOES belong; reject only when mismatch.
    if cred.get("workspace_id") != workspace_id:
        return _err(
            "CONFLICT",
            "Credential does not belong to the given workspace (workspace_id mismatch).",
            workspace_id=workspace_id,
            credential_id=credential_id,
            credential_workspace_id=cred.get("workspace_id"),
        )

    # Lifecycle rules
    current_status = cred.get("status")
    if current_status not in ("active", "disabled", "revoked"):
        return _err("CONFLICT", "Datastore corrupted: credential has invalid status.", credential_id=credential_id, status=current_status)

    if current_status == "revoked":
        # Once revoked, refuse any updates
        return _err("INVALID_TRANSITION", "Credential is revoked and cannot be updated.", credential_id=credential_id)

    if status is not None:
        allowed = {
            "active": ("disabled", "revoked"),
            "disabled": ("active", "revoked"),
            "revoked": (),
        }
        if status == current_status:
            # idempotent status set is allowed
            pass
        else:
            if status not in allowed.get(current_status, ()):
                return _err(
                    "INVALID_TRANSITION",
                    "Invalid credential status transition.",
                    from_status=current_status,
                    to_status=status,
                    credential_id=credential_id,
                )

    # Key rotation rules + uniqueness constraint: unique(workspace_id, provider, key_fingerprint)
    changed = False
    now = _now()

    if api_key is not None:
        new_fp = _fingerprint(api_key)
        provider = cred.get("provider")
        if provider != "giphy":
            return _err("CONFLICT", "Datastore corrupted: credential provider must be 'giphy'.", credential_id=credential_id, provider=provider)

        # If fingerprint unchanged, treat as idempotent rotate (still update updated_at)
        if new_fp != cred.get("key_fingerprint"):
            for c in creds:
                if not isinstance(c, dict):
                    continue
                if c.get("id") == credential_id:
                    continue
                if c.get("workspace_id") == workspace_id and c.get("provider") == "giphy" and c.get("key_fingerprint") == new_fp:
                    return _err(
                        "CONFLICT",
                        "Duplicate credential for this workspace/provider/key_fingerprint (unique(workspace_id, provider, key_fingerprint)).",
                        workspace_id=workspace_id,
                        provider="giphy",
                        key_fingerprint=new_fp,
                    )
            cred["key_fingerprint"] = new_fp
            cred["api_key_ciphertext"] = _ciphertext_placeholder(api_key)
            changed = True

    if status is not None and status != current_status:
        cred["status"] = status
        changed = True

    # Even if change is idempotent (same status / same key), updated_at should reflect the update attempt?
    # Real systems vary; but "no success without effect" applies. Ensure at least updated_at moves only if there is
    # an actual change OR a true idempotent set (status same / key same) should still be considered an effect? We'll
    # only succeed if something changes or the caller requested a state equal to current (idempotent).
    requested_idempotent = False
    if status is not None and status == current_status:
        requested_idempotent = True
    if api_key is not None and _fingerprint(api_key) == cred.get("key_fingerprint"):
        requested_idempotent = True

    if not changed and not requested_idempotent:
        return _err("NOT_FOUND", "No update applied.", credential_id=credential_id)

    cred["updated_at"] = now
    creds[cred_idx] = cred
    _save("api_credentials.json", creds)

    # Do not return api_key_ciphertext (key material) - return metadata row as stored (it includes ciphertext in schema,
    # but description says not returned). So redact it.
    resp = dict(cred)
    if "api_key_ciphertext" in resp:
        resp["api_key_ciphertext"] = None

    return {"credential": resp}

def list_gif_requests(workspace_id, tool_name=None, status=None, credential_id=None, created_from=None, created_to=None, limit=None, offset=None, sort=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0335000" if __import__("os").path.isdir("./environment_mix/0335000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gph_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if tool_name is not None and tool_name not in ("search_gifs", "get_random_gif", "get_trending_gifs"):
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if credential_id is not None:
        if not isinstance(credential_id, str) or not re.match(r"^gph_cred_[A-Za-z0-9]+$", credential_id):
            return _err("VALIDATION_ERROR", "Invalid credential_id.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if offset is None:
        offset = 0
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "Invalid offset.")
    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "Invalid sort.")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"Invalid {field}.")
        try:
            # Accept ...Z or offset; normalize Z
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"Invalid {field}, must be date-time.")
    dt_from, e = _parse_dt(created_from, "created_from")
    if e: return e
    dt_to, e = _parse_dt(created_to, "created_to")
    if e: return e
    if dt_from and dt_to and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "created_from must be <= created_to.")

    # Load + check workspace exists
    workspaces = _load("workspaces.json")
    ws_exists = any(isinstance(r, dict) and r.get("id") == workspace_id for r in workspaces)
    if not ws_exists:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    reqs = _load("gif_requests.json")

    def _row_dt(row):
        v = row.get("created_at")
        if not isinstance(v, str):
            return None
        try:
            vv = v[:-1] + "+00:00" if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(vv)
        except Exception:
            return None

    out = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if credential_id is not None and r.get("credential_id") != credential_id:
            continue
        cd = _row_dt(r)
        if dt_from is not None and cd is not None and cd < dt_from:
            continue
        if dt_to is not None and cd is not None and cd >= dt_to:
            continue
        # If date parsing fails, include row (do not silently drop audits)
        if dt_from is not None and cd is None:
            pass
        if dt_to is not None and cd is None:
            pass

        # Return request rows (no raw upstream responses are in this table anyway)
        out.append(r)

    reverse = (sort == "created_at_desc")
    def _sort_key(r):
        cd = _row_dt(r)
        # Put unparsable at end deterministically
        return (cd is None, cd or datetime.datetime.min)
    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    has_more = offset + limit < total
    next_offset = offset + limit if has_more else None

    return {
        "requests": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_offset": next_offset
        }
    }
